/* eslint-disable @typescript-eslint/no-require-imports -- standalone Node script */
/*
 * Browser verification of the gamification experience upgrade (docs/GAMIFICATION_PRODUCT_REVIEW.md, "After the upgrade"). Real web export, MOCK mode, simulated Apple Health
 * provider, synthetic data. "ui" = real taps; "seed" = the same screens on persisted dev-store history generated by the dev store (the starting point only; every reward below is
 * earned by a real tap). Haptics cannot be observed in a browser (expo-haptics is a no-op on the web): marked native-only.
 * Usage: pnpm export:web && node e2e/gamification-upgrade.cjs   Output: docs/review-shots/after-*.png and docs/review-shots/results-upgrade.json
 */
const { chromium } = require('playwright');
const fs = require('node:fs');
const { createAccountViaPin, onboard, enterPin } = require('./auth.cjs');

const OUT = process.env.REVIEW_OUT || '../../docs/review-shots';
const SEEDS = process.env.SEED_DIR || '/tmp/seeds';
fs.mkdirSync(OUT, { recursive: true });
const results = {};
const base = 'http://127.0.0.1:8099';

async function main() {
  const { serve } = await import('./serve.mjs');
  const srv = await serve(8099);
  const browser = await chromium.launch();

  const tools = (p) => {
    const go = async (path, wait = 900) => {
      await p.evaluate((u) => {
        window.history.pushState({}, '', u);
        window.dispatchEvent(new PopStateEvent('popstate'));
      }, path);
      await p.waitForTimeout(wait);
    };
    const body = () => p.evaluate(() => document.body.innerText);
    const scroll = async (text) => {
      await p
        .getByText(text, { exact: false })
        .last()
        .scrollIntoViewIfNeeded()
        .catch(() => {});
      await p.waitForTimeout(450);
    };
    const shot = (name) => p.screenshot({ path: `${OUT}/after-${name}.png` });
    const xp = async () => {
      await p.waitForTimeout(1300); // the XP number counts up to its value
      const m = /Level \d+\s+(\d[\d,]*) XP\b/.exec(await body()); // the level card, never a "+N XP" in a banner
      return m ? Number(m[1].replace(',', '')) : null;
    };
    const waitText = async (re, ms = 6000) => {
      const t0 = Date.now();
      while (Date.now() - t0 < ms) {
        if (re.test(await body())) return true;
        await p.waitForTimeout(150);
      }
      return false;
    };
    return { go, body, scroll, shot, xp, waitText };
  };
  const openSeed = async (name, opts = {}) => {
    const ctx = await browser.newContext({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 1.5,
      ...(opts.reduced ? { reducedMotion: 'reduce' } : {}),
    });
    const seed = JSON.parse(fs.readFileSync(`${SEEDS}/${name}.json`, 'utf8'));
    await ctx.addInitScript((s) => {
      for (const [k, v] of Object.entries(s))
        if (!localStorage.getItem(k)) localStorage.setItem(k, v);
    }, seed);
    const p = await ctx.newPage();
    p.setDefaultTimeout(6000);
    const errors = [];
    p.on('pageerror', (e) => errors.push(e.message));
    await p.goto(base);
    await p.waitForTimeout(1500);
    if (
      await p
        .getByText('Protect your account with a PIN')
        .first()
        .isVisible()
        .catch(() => false)
    ) {
      await enterPin(p);
      await p.getByText('Confirm your PIN').first().waitFor({ state: 'visible' });
      await enterPin(p);
      await p
        .getByRole('button', { name: 'Protect my account', exact: true })
        .locator('visible=true')
        .last()
        .click();
    }
    await p.waitForTimeout(2200); // first confirmed answer = the silent baseline
    return { p, ctx, errors, ...tools(p) };
  };
  const step = async (key, fn) => {
    try {
      results[key] = { ok: true, ...(await fn()) };
    } catch (e) {
      results[key] = { ok: false, error: String(e.message).split('\n').slice(0, 4).join(' | ') };
    }
    console.log(results[key].ok ? 'OK  ' : 'FAIL', key, results[key].ok ? '' : results[key].error);
  };
  const importViaSettings = async (s) => {
    await s.go('/privacy');
    await s.p.getByRole('switch', { name: 'Import workouts from Apple Health' }).last().click();
  };

  // ---- R1: Home updates promptly (new account, UI only) ----
  await step('R1-prompt-update', async () => {
    const ctx = await browser.newContext({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 1.5,
    });
    const p = await ctx.newPage();
    p.setDefaultTimeout(6000);
    const s = tools(p);
    await p.goto(base);
    await p.waitForTimeout(2500);
    await createAccountViaPin(p);
    await onboard(p);
    await p.waitForTimeout(2200);
    await p.getByLabel('New habit').last().fill('Stretch two minutes');
    await p.getByRole('button', { name: 'Add habit' }).last().click();
    await p.waitForTimeout(900);
    await s.scroll('Your progress');
    await s.shot('r1-01-before-tick');
    const before = await s.xp();
    const t0 = Date.now();
    await p
      .getByRole('checkbox', { name: /Stretch two minutes: not done today/ })
      .last()
      .click();
    const updated = await s.waitText(/Level 1\s+5 XP\b/, 5000);
    const ms = Date.now() - t0;
    await s.scroll('Your progress');
    await s.shot('r1-02-after-tick-card-updated');
    const text = await s.body();
    return {
      xpBefore: before,
      xpAfter: await s.xp(),
      updatedWithinMs: updated ? ms : null,
      streakLine: text.match(
        /\d+-day streak|Move for 10 minutes or tick a habit to start a streak\./,
      )?.[0],
      bannerShown: /Nice work/.test(text),
      bannerLines: text
        .split('\n')
        .filter((l) => /\+\d+ XP/.test(l))
        .slice(0, 3),
    };
  });

  // ---- a qualifying workout (scheduled for today and marked done), XP shown only once confirmed ----
  await step('workout-xp-feedback', async () => {
    const ctx = await browser.newContext({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 1.5,
    });
    const p = await ctx.newPage();
    p.setDefaultTimeout(8000);
    const s = tools(p);
    await p.goto(base);
    await p.waitForTimeout(2500);
    await createAccountViaPin(p);
    await onboard(p);
    await p.waitForTimeout(2200);
    const btn = (n) => p.getByRole('button', { name: n }).last();
    await p.getByRole('tab', { name: 'Dance', exact: true }).click();
    await p.waitForTimeout(1200);
    await btn(/Quick Fit/).click();
    await p.waitForTimeout(800);
    const vis = () => p.getByRole('button', { name: 'Schedule it' }).locator('visible=true');
    await vis().first().click();
    await p.waitForTimeout(600);
    await vis().last().click();
    await p.waitForTimeout(900);
    const sched = (await s.body()).match(/Scheduled for[^\n]*/)?.[0];
    await s.go('/dance/schedule', 1200);
    await s.shot('workout-01-scheduled');
    await btn('Mark done').click();
    const sawChecking = await s.waitText(/Checking your progress/, 800);
    await p.waitForTimeout(800);
    await s.go('/dance', 1200);
    await s.waitText(/Nice work/, 4000);
    await s.shot('workout-02-dance-tab-xp-banner');
    await s.go('/', 1200);
    await s.scroll('Your progress');
    await s.shot('workout-03-home-after-workout');
    const t = await s.body();
    return {
      scheduled: sched,
      bannerLines: t
        .split('\n')
        .filter((l) => /\+\d+ XP|Level \d+ reached|Quest done|Brought/.test(l))
        .slice(0, 4),
      xpOnLevelCard: await s.xp(),
      checkingShown: sawChecking,
    };
  });

  // ---- level-up + Apple Health reward summary + animated bar ----
  await step('levelup-and-health-summary', async () => {
    const s = await openSeed('levelup');
    const before = await s.xp();
    await s.scroll('Your progress');
    await s.shot('levelup-01-home-before');
    await importViaSettings(s);
    const sawToast = await s.waitText(/Level \d+! You earned it\./, 6000);
    await s.shot('levelup-02-toast-and-settings-banner');
    await s.go('/');
    await s.scroll('Your progress');
    await s.waitText(/Nice work/, 3000);
    await s.shot('levelup-03-home-after-summary');
    const t = await s.body();
    return {
      xpBefore: before,
      xpAfter: await s.xp(),
      toastShown: sawToast,
      bannerLines: t
        .split('\n')
        .filter((l) => /\+\d+ XP|Level \d+ reached|Brought in/.test(l))
        .slice(0, 4),
      errors: s.errors,
    };
  });

  // ---- streak milestone + badge unlock + collection ----
  await step('streak-milestone-and-badge', async () => {
    const s = await openSeed('streak6');
    const before = await s.body();
    await s.scroll('Your progress');
    await s.shot('streak-01-before-day6');
    await s.p
      .getByRole('checkbox', { name: /Stretch two minutes: not done today/ })
      .last()
      .click();
    const toast = await s.waitText(/active days in a row!|New badge:/, 6000);
    await s.shot('streak-02-toast');
    await s.scroll('Your progress');
    await s.waitText(/Nice work/, 3000);
    await s.shot('streak-03-home-banner');
    const t = await s.body();
    await s.go('/progress');
    await s.scroll('Badges');
    await s.shot('streak-04-badge-collection');
    return {
      streakBefore: before.match(/\d+-day streak/)?.[0],
      streakAfter: t.match(/\d+-day streak/)?.[0],
      toastShown: toast,
      bannerLines: t
        .split('\n')
        .filter((l) => /active days in a row|New badge|\+\d+ XP|Quest done/.test(l))
        .slice(0, 5),
    };
  });

  // ---- cosmetic unlock + wardrobe equip ----
  await step('cosmetic-unlock-and-equip', async () => {
    const s = await openSeed('cosmetic4');
    await s.shot('cosmetic-01-home-before');
    await importViaSettings(s);
    const toast = await s.waitText(/Pulse unlocked:|Level \d+! You earned it\./, 6000);
    await s.go('/');
    await s.waitText(/Nice work/, 3000);
    await s.shot('cosmetic-02-home-unlocked-banner');
    await s.go('/progress');
    await s.scroll('Pulse’s wardrobe');
    await s.shot('cosmetic-03-wardrobe');
    const label = async () =>
      (await s.p
        .getByLabel(/^Pulse, wearing/)
        .first()
        .getAttribute('aria-label')
        .catch(() => null)) ?? (await s.body()).match(/Pulse, wearing [^\n]*/)?.[0];
    const worn = await label();
    await s.p
      .getByRole('switch', { name: /^Headband/ })
      .last()
      .click();
    await s.p.waitForTimeout(700);
    await s.shot('cosmetic-04-wardrobe-taken-off');
    const off = await label();
    await s.p
      .getByRole('switch', { name: /^Headband/ })
      .last()
      .click();
    await s.p.waitForTimeout(500);
    const on = await label();
    return { toastShown: toast, wornAfterUnlock: worn, afterTakeOff: off, afterWearAgain: on };
  });

  // ---- group goal completion (shared) ----
  await step('group-goal-completion', async () => {
    const s = await openSeed('group');
    await s.go('/friends');
    await s.scroll('Move together');
    await s.p.mouse.move(195, 420);
    await s.shot('group-01-before');
    await importViaSettings(s);
    await s.p.waitForTimeout(1500);
    await s.go('/friends', 2500);
    const toast = await s.waitText(/Goal reached together/, 6000);
    await s.p.mouse.move(195, 420);
    await s.p.mouse.wheel(0, 640);
    await s.p.waitForTimeout(700);
    await s.shot('group-02-goal-reached');
    await s.go('/friends', 1500);
    await s.scroll('Goal reached together');
    await s.shot('group-03-card-progress');
    const t = await s.body();
    return {
      celebrationShown: toast || /Group goal reached/.test(t),
      cardText: t
        .split('\n')
        .filter((l) => /Goal reached together|of 4|Each person/.test(l))
        .slice(0, 4),
    };
  });

  // ---- R2: celebrations Off removes the toast, banner and motion; numbers still update ----
  await step('R2-celebrations-off', async () => {
    const s = await openSeed('levelup');
    await s.go('/goals', 1200);
    await s.scroll('Pulse celebrations');
    await s.p.getByRole('button', { name: 'Off', exact: true }).last().click();
    await s.p.waitForTimeout(700);
    await s.shot('r2-01-celebrations-off');
    const before = await s.xp();
    await importViaSettings(s);
    await s.p.waitForTimeout(2500);
    const settingsText = await s.body();
    await s.shot('r2-02-settings-after-import-no-banner');
    await s.go('/');
    await s.scroll('Your progress');
    await s.p.waitForTimeout(800);
    await s.shot('r2-03-home-numbers-updated-quietly');
    const t = await s.body();
    return {
      xpBefore: before,
      xpAfter: await s.xp(),
      toastShown: /Level \d+! You earned it\./.test(settingsText),
      bannerShown: /Nice work/.test(settingsText + t),
      levelNow: t.match(/Level \d+/)?.[0],
    };
  });

  // ---- Reduce Motion: bars do not animate; with motion on they do ----
  await step('reduce-motion-bars', async () => {
    const sample = async (s) => {
      await s.go('/privacy', 300);
      await s.p.evaluate(() => {
        history.pushState({}, '', '/progress');
        dispatchEvent(new PopStateEvent('popstate'));
      });
      const seen = [];
      const t0 = Date.now();
      while (Date.now() - t0 < 2200) {
        const v = await s.p.evaluate(() => {
          const el = document.querySelector('[role="progressbar"] > div');
          return el ? getComputedStyle(el).transform : null;
        });
        if (v && !seen.includes(v)) seen.push(v);
        await s.p.waitForTimeout(40);
      }
      return {
        distinctPositions: seen.length,
        first: seen[0] ?? null,
        last: seen[seen.length - 1] ?? null,
      };
    };
    const normal = await openSeed('veteran-copy');
    const a = await sample(normal);
    const reduced = await openSeed('veteran-copy', { reduced: true });
    const b = await sample(reduced);
    return { motionOn: a, reduceMotion: b };
  });

  // ---- visuals on the long history: level card, badge collection, season, wardrobe, league ----
  await step('veteran-visuals', async () => {
    const seed = '/tmp/seeds/veteran.json';
    if (!fs.existsSync(seed)) return { skipped: 'no veteran seed' };
    fs.copyFileSync(seed, `${SEEDS}/veteran-copy.json`);
    const s = await openSeed('veteran-copy');
    await s.scroll('Your progress');
    await s.shot('vet-01-home-progress');
    await s.go('/progress');
    await s.scroll('Level 1');
    await s.shot('vet-02-progress-level');
    await s.scroll('Badges');
    await s.shot('vet-03-badge-collection');
    await s.scroll('Season challenge');
    await s.shot('vet-04-season');
    await s.scroll('Pulse’s wardrobe');
    await s.shot('vet-05-wardrobe');
    await s.go('/friends');
    await s.scroll('Friends league');
    await s.shot('vet-06-league');
    await s.go('/dance');
    await s.scroll('This week');
    await s.shot('vet-07-workouts-week-strip');
    return { errors: s.errors };
  });

  fs.writeFileSync(`${OUT}/results-upgrade.json`, JSON.stringify(results, null, 2));
  await browser.close();
  srv.close();
}
main().catch((e) => {
  console.error(e);
  process.exit(1);
});
